package net.java21.data2flow.core.external.provider;

import java.time.LocalDate;
import java.util.List;

/**
 * 가짜 공휴일(ADR-040): 서비스 키 없이 쓰는 내장 목록(대한민국 2025~2027년 공휴일·대체공휴일, 관보 공고 기준). 목록 밖의 해는 고정 날짜
 * 공휴일(신정·삼일절·어린이날·현충일·광복절·개천절·한글날·성탄절)만 준다(음력 명절은 키를 넣어 어댑터로 받는다).
 */
public class FixedHolidayProvider implements HolidayProvider {

    static final List<Holiday> KNOWN = List.of(
            h("2025-01-01", "1월1일"), h("2025-01-28", "설날"), h("2025-01-29", "설날"), h("2025-01-30", "설날"),
            h("2025-03-01", "삼일절"), h("2025-03-03", "대체공휴일"), h("2025-05-05", "어린이날"), h("2025-05-05", "부처님오신날"),
            h("2025-05-06", "대체공휴일"), h("2025-06-06", "현충일"), h("2025-08-15", "광복절"), h("2025-10-03", "개천절"),
            h("2025-10-05", "추석"), h("2025-10-06", "추석"), h("2025-10-07", "추석"), h("2025-10-08", "대체공휴일"),
            h("2025-10-09", "한글날"), h("2025-12-25", "기독탄신일"),
            h("2026-01-01", "1월1일"), h("2026-02-16", "설날"), h("2026-02-17", "설날"), h("2026-02-18", "설날"),
            h("2026-03-01", "삼일절"), h("2026-03-02", "대체공휴일"), h("2026-05-05", "어린이날"), h("2026-05-24", "부처님오신날"),
            h("2026-05-25", "대체공휴일"), h("2026-06-03", "전국동시지방선거"), h("2026-06-06", "현충일"), h("2026-08-15", "광복절"),
            h("2026-08-17", "대체공휴일"), h("2026-09-24", "추석"), h("2026-09-25", "추석"), h("2026-09-26", "추석"),
            h("2026-10-03", "개천절"), h("2026-10-05", "대체공휴일"), h("2026-10-09", "한글날"), h("2026-12-25", "기독탄신일"),
            h("2027-01-01", "1월1일"), h("2027-02-06", "설날"), h("2027-02-07", "설날"), h("2027-02-08", "설날"),
            h("2027-02-09", "대체공휴일"), h("2027-03-01", "삼일절"), h("2027-05-05", "어린이날"), h("2027-05-13", "부처님오신날"),
            h("2027-06-06", "현충일"), h("2027-08-15", "광복절"), h("2027-08-16", "대체공휴일"), h("2027-09-14", "추석"),
            h("2027-09-15", "추석"), h("2027-09-16", "추석"), h("2027-10-03", "개천절"), h("2027-10-04", "대체공휴일"),
            h("2027-10-09", "한글날"), h("2027-10-11", "대체공휴일"), h("2027-12-25", "기독탄신일"), h("2027-12-27", "대체공휴일"));

    private static Holiday h(String date, String name) {
        return new Holiday(LocalDate.parse(date), name);
    }

    @Override
    public ProviderDescriptor descriptor() {
        return new ProviderDescriptor("FIXED_HOLIDAY", true, true);
    }

    @Override
    public List<Holiday> holidays(int year) {
        List<Holiday> known = KNOWN.stream().filter(h -> h.date().getYear() == year).toList();
        if (!known.isEmpty()) {
            return known;
        }
        return List.of(h(year + "-01-01", "1월1일"), h(year + "-03-01", "삼일절"), h(year + "-05-05", "어린이날"),
                h(year + "-06-06", "현충일"), h(year + "-08-15", "광복절"), h(year + "-10-03", "개천절"), h(year + "-10-09", "한글날"),
                h(year + "-12-25", "기독탄신일"));
    }
}
